const handleNavigateToHome = (
  destination: { [key: string]: number | undefined },
  actionType: string,
  isBottomBar: boolean,
) => {
  const scrollVerticalIndex = destination?.[actionType];

  if (isBottomBar) {
    const currentRouteName = navigationRef.getCurrentRoute()?.name;

    if (currentRouteName === (ENUM_SCREEN.HOME_PAGE as string)) {
      navigationRef.navigate({
        name: ENUM_APP.HOME_APP,
        params: buildHomeNavigateParams(scrollVerticalIndex),
        merge: true,
      });
      return;
    }

    resetRootToHome(scrollVerticalIndex);
    return;
  }

  navigationRef.navigate(ENUM_APP.HOME_APP, {
    ...buildHomeNavigateParams(scrollVerticalIndex),
  });
};

